  margin-top: var(--space-xl);
}

.testimonials-nav button {
  width: 48px;
  height: 48px;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  font-size: 1.25rem;
  color: var(--text-muted);
}

.testimonials-nav button:hover {
  border-color: var(--primary);
  color: var(--primary);
}

/* ---------- Pricing Overview ---------- */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-xl);
}

.pricing-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  position: relative;
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: var(--radius-sm);
  text-transform: uppercase;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
}

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: var(--space-xs);
}

.pricing-price span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--text-muted);
}

.pricing-desc {
  color: var(--text-muted);
  font-size: 0.9375rem;
  margin-bottom: var(--space-lg);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-bottom: var(--space-xl);
}

.pricing-features li {
  font-size: 0.9375rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.pricing-features li::before {
  content: "✓";
  color: var(--primary);
  font-weight: 700;
}

/* ---------- FAQ Accordion ---------- */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.faq-item {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.faq-question {
  width: 100%;
  padding: var(--space-lg);
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-md);
  transition: background var(--transition);
}

.faq-question:hover {
  background: var(--bg-alt);
}

.faq-icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition);
  flex-shrink: 0;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer-inner {
  padding: 0 var(--space-lg) var(--space-lg);
  color: var(--text-muted);
  line-height: 1.7;
}

/* ---------- CTA Banner ---------- */
.cta-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: #fff;
  text-align: center;
  padding: var(--space-3xl) var(--space-lg);
}

.cta-banner h2 {
  color: #fff;
  margin-bottom: var(--space-md);
}

.cta-banner p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto var(--space-xl);
}

.cta-banner .btn-white {
  background: #fff;
  color: var(--primary);
}

.cta-banner .btn-white:hover {
  background: var(--bg-alt);
}

/* ---------- Footer ---------- */
.footer {
  background: var(--bg-dark);
  color: #fff;
  padding: var(--space-3xl) var(--space-lg) var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-3xl);
}

.footer-brand p {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  margin-top: var(--space-md);
  max-width: 300px;
  line-height: 1.7;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-lg);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col a {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--space-xl);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.footer-bottom p {
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: var(--space-lg);
}

.footer-legal a {
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
}

.footer-legal a:hover {
  color: #fff;
}

/* ---------- Feature Cards ---------- */
.feature-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-xl);
}

.feature-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--primary-light);
  box-shadow: var(--shadow-lg);
}

.feature-card-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
  color: #fff;
  font-size: 1.25rem;
}

.feature-card h3 {
  font-size: 1.125rem;
  margin-bottom: var(--space-md);
}

.feature-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ---------- Steps ---------- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.step-card {
  text-align: center;
  padding: var(--space-xl);
}

.step-number {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  color: #fff;
  margin: 0 auto var(--space-lg);
}

.step-card h3 {
  margin-bottom: var(--space-md);
}

.step-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ---------- Tools Grid ---------- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-md);
}

.tool-item {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-md) var(--space-lg);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  transition: all var(--transition);
}

.tool-item:hover {
  border-color: var(--primary-light);
  color: var(--primary);
}

.tool-item::before {
  content: "+";
  color: var(--primary);
  font-weight: 700;
}

/* ---------- Resource Cards ---------- */
.resource-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-xl);
}

.resource-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  transition: all var(--transition);
}

.resource-card:hover {
  border-color: var(--primary-light);
  box-shadow: var(--shadow-lg);
}

.resource-card span {
  display: inline-block;
  background: var(--bg-alt);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-md);
}

.resource-card h3 {
  font-size: 1rem;
  margin-bottom: var(--space-sm);
}

.resource-card p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* ---------- Spotlight Cards ---------- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.spotlight-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  text-align: center;
  transition: all var(--transition);
}

.spotlight-card:hover {
  border-color: var(--primary-light);
  box-shadow: var(--shadow-lg);
}

.spotlight-logo {
  width: 80px;
  height: 80px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-lg);
  color: #fff;
  font-size: 1.5rem;
  font-weight: 800;
}

.spotlight-card h3 {
  margin-bottom: var(--space-sm);
}

.spotlight-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ---------- Value Props ---------- */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.value-prop-card {
  text-align: center;
  padding: var(--space-xl);
}

.value-prop-icon {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-lg);
  color: #fff;
  font-size: 1.5rem;
}

.value-prop-card h3 {
  margin-bottom: var(--space-md);
}

.value-prop-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ---------- File Types Grid ---------- */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-md);
}

.file-type-item {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  text-align: center;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text);
  transition: all var(--transition);
}

.file-type-item:hover {
  border-color: var(--primary-light);
  color: var(--primary);
}

/* ---------- Scroll Animations ---------- */
.animate-on-scroll {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .why-tab-content-inner {
    grid-template-columns: 1fr;
  }

  .testimonial-card {
    flex: 0 0 calc(50% - var(--space-lg));
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--bg);
    flex-direction: column;
    padding: var(--space-lg);
    border-bottom: 1px solid var(--border);
    box-shadow: var(--shadow-lg);
    gap: var(--space-md);
  }

  .nav-links.open {
    display: flex;
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .testimonial-card {
    flex: 0 0 calc(100% - var(--space-lg));
  }

  .steps-grid,
  .spotlight-grid,
  .value-props-grid {
    grid-template-columns: 1fr;
  }

  .stats-bar-inner {
    gap: var(--space-xl);
  }

  .hero-cta {
    flex-direction: column;
    align-items: center;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .section {
    padding: var(--space-2xl) var(--space-md);
  }

  .hero {
    padding-top: 6rem;
  }

  .tab-toggle {
    flex-direction: column;
    width: 100%;
  }

  .tab-toggle-btn {
    width: 100%;
  }
