/* ========================================
   LearnForge — Corporate Website Styles
   Modern, Bold, Professional
   ======================================== */

/* ---------- CSS Variables ---------- */
:root {
  /* Brand Colors - Electric Blue + Coral accents on clean white */
  --primary: #2563EB;
  --primary-dark: #1D4ED8;
  --primary-light: #3B82F6;
  --accent: #F97316;
  --accent-light: #FB923C;

  /* Neutrals */
  --bg: #FFFFFF;
  --bg-alt: #F8FAFC;
  --bg-dark: #0F172A;
  --text: #0F172A;
  --text-muted: #64748B;
  --text-light: #94A3B8;
  --border: #E2E8F0;
  --border-dark: #CBD5E1;

  /* Typography */
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;

  /* Borders */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  /* Transitions */
  --transition: 0.2s ease;
  --transition-slow: 0.3s ease;
}

/* ---------- Reset & Base ---------- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--primary-dark);
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ---------- Typography ---------- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--text);
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

.text-muted { color: var(--text-muted); }
.text-light { color: var(--text-light); }

/* ---------- Container ---------- */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.container-narrow {
  max-width: 960px;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-lg);
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 2px solid var(--border-dark);
}

.btn-secondary:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.btn-white {
  background: #fff;
  color: var(--primary);
}

.btn-white:hover {
  background: var(--bg-alt);
  transform: translateY(-1px);
}

.btn-lg {
  padding: 1rem 2rem;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

/* ---------- Navigation ---------- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.nav-logo span {
  color: var(--primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.nav-link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-muted);
  transition: color var(--transition);
  position: relative;
}

.nav-link:hover {
  color: var(--text);
}

.nav-link.active {
  color: var(--primary);
}

.nav-cta .btn {
  padding: 0.625rem 1.25rem;
}

.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  border-radius: 2px;
  transition: var(--transition);
}

/* ---------- Hero Section ---------- */
.hero {
  padding: 8rem var(--space-lg) 4rem;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-alt) 0%, var(--bg) 100%);
}

.hero-title {
  font-size: clamp(2.5rem, 6vw, 4rem);
  font-weight: 800;
  margin-bottom: var(--space-lg);
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
}

.hero-subtitle {
  font-size: clamp(1.125rem, 2vw, 1.375rem);
  color: var(--text-muted);
  max-width: 700px;
  margin: 0 auto var(--space-xl);
  line-height: 1.7;
}

.hero-cta {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: var(--space-2xl);
}

/* Tab Toggle */
.tab-toggle {
  display: inline-flex;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 4px;
  margin-bottom: var(--space-xl);
}

.tab-toggle-btn {
  padding: 0.625rem 1.5rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: var(--radius-lg);
  transition: all var(--transition);
}

.tab-toggle-btn.active {
  background: var(--primary);
  color: #fff;
}

.tab-toggle-btn:not(.active):hover {
  color: var(--text);
}

.hero-preview {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-lg);
  max-width: 900px;
  margin: 0 auto;
  box-shadow: var(--shadow-lg);
}

.preview-placeholder {
  background: linear-gradient(135deg, var(--bg-alt) 0%, #E2E8F0 100%);
  border-radius: var(--radius-lg);
  padding: var(--space-3xl) var(--space-xl);
  text-align: center;
}

.preview-placeholder p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* ---------- Stats Bar ---------- */
.stats-bar {
  background: var(--bg-dark);
  color: #fff;
  padding: var(--space-2xl) var(--space-lg);
}

.stats-bar-inner {
  display: flex;
  justify-content: center;
  gap: var(--space-3xl);
  flex-wrap: wrap;
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: #fff;
  display: block;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  margin-top: var(--space-xs);
}

/* ---------- Section Spacing ---------- */
.section {
  padding: var(--space-3xl) var(--space-lg);
}

.section-alt {
  background: var(--bg-alt);
}

.section-dark {
  background: var(--bg-dark);
  color: #fff;
}

.section-dark h2,
.section-dark h3 {
  color: #fff;
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-3xl);
}

.section-header h2 {
  margin-bottom: var(--space-md);
}

.section-header p {
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto;
  font-size: 1.125rem;
}

.section-dark .section-header p {
  color: rgba(255,255,255,0.7);
}

/* ---------- Product Grid ---------- */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--space-xl);
}

.product-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  transition: all var(--transition);
}

.product-card:hover {
  border-color: var(--primary-light);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.product-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
  font-size: 1.5rem;
}

.product-card h3 {
  margin-bottom: var(--space-md);
}

.product-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ---------- Why Choose Us / Tabs ---------- */
.why-tabs {
  display: flex;
  justify-content: center;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-bottom: var(--space-2xl);
}

.why-tab-btn {
  padding: 0.75rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-muted);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  transition: all var(--transition);
}

.why-tab-btn.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.why-tab-btn:not(.active):hover {
  border-color: var(--primary-light);
  color: var(--primary);
}

.why-tab-content {
  display: none;
  animation: fadeIn 0.3s ease;
}

.why-tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.why-tab-content-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-2xl);
  align-items: center;
}

.why-tab-text h3 {
  margin-bottom: var(--space-lg);
  color: var(--primary);
}

.why-tab-text ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.why-tab-text li {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  color: var(--text-muted);
  font-size: 1rem;
}

.why-tab-text li::before {
  content: "✓";
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  background: var(--primary);
  color: #fff;
  border-radius: 50%;
  font-size: 0.75rem;
  flex-shrink: 0;
  margin-top: 2px;
}

.why-tab-visual {
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 1.25rem;
  font-weight: 600;
}

/* ---------- Integrations Grid ---------- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--space-lg);
}

.integration-item {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  text-align: center;
  transition: all var(--transition);
}

.integration-item:hover {
  border-color: var(--primary-light);
  box-shadow: var(--shadow-md);
}

.integration-logo {
  width: 48px;
  height: 48px;
  background: var(--bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-md);
  font-weight: 700;
  color: var(--text);
}

.integration-item span {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* ---------- Testimonials Carousel ---------- */
.testimonials-wrapper {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  gap: var(--space-xl);
  transition: transform 0.4s ease;
}

.testimonial-card {
  flex: 0 0 calc(33.333% - var(--space-lg));
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
}

.testimonial-quote {
  font-size: 2rem;
  color: var(--primary);
  margin-bottom: var(--space-md);
  line-height: 1;
}

.testimonial-text {
  font-size: 1rem;
  color: var(--text);
  line-height: 1.7;
  margin-bottom: var(--space-lg);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.testimonial-avatar {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 700;
}

.testimonial-meta h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
}

.testimonial-meta span {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.testimonial-tag {
  display: inline-block;
  background: var(--primary);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-sm);
  margin-top: var(--space-sm);
}

.testimonials-nav {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.testimonials-nav button {
  width: 48px;
  height: 48px;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  font-size: 1.25rem;
  color: var(--text-muted);
}

.testimonials-nav button:hover {
  border-color: var(--primary);
  color: var(--primary);
}

/* ---------- Pricing Overview ---------- */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-xl);
}

.pricing-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  position: relative;
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: var(--radius-sm);
  text-transform: uppercase;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
}

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: var(--space-xs);
}

.pricing-price span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--text-muted);
}

.pricing-desc {
  color: var(--text-muted);
  font-size: 0.9375rem;
  margin-bottom: var(--space-lg);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-bottom: var(--space-xl);
}

.pricing-features li {
  font-size: 0.9375rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.pricing-features li::before {
  content: "✓";
  color: var(--primary);
  font-weight: 700;
}

/* ---------- FAQ Accordion ---------- */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.faq-item {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.faq-question {
  width: 100%;
  padding: var(--space-lg);
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-md);
  transition: background var(--transition);
}

.faq-question:hover {
  background: var(--bg-alt);
}

.faq-icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition);
  flex-shrink: 0;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer-inner {
  padding: 0 var(--space-lg) var(--space-lg);
  color: var(--text-muted);
  line-height: 1.7;
}

/* ---------- CTA Banner ---------- */
.cta-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: #fff;
  text-align: center;
  padding: var(--space-3xl) var(--space-lg);
}

.cta-banner h2 {
  color: #fff;
  margin-bottom: var(--space-md);
}

.cta-banner p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto var(--space-xl);
}

.cta-banner .btn-white {
  background: #fff;
  color: var(--primary);
}

.cta-banner .btn-white:hover {
  background: var(--bg-alt);
}

/* ---------- Footer ---------- */
.footer {
  background: var(--bg-dark);
  color: #fff;
  padding: var(--space-3xl) var(--space-lg) var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-3xl);
}

.footer-brand p {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  margin-top: var(--space-md);
  max-width: 300px;
  line-height: 1.7;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-lg);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col a {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--space-xl);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.footer-bottom p {
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: var(--space-lg);
}

.footer-legal a {
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
}

.footer-legal a:hover {
  color: #fff;
}

/* ---------- Feature Cards ---------- */
.feature-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-xl);
}

.feature-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--primary-light);
  box-shadow: var(--shadow-lg);
}

.feature-card-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
  color: #fff;
  font-size: 1.25rem;
}

.feature-card h3 {
  font-size: 1.125rem;
  margin-bottom: var(--space-md);
}

.feature-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ---------- Steps ---------- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.step-card {
  text-align: center;
  padding: var(--space-xl);
}

.step-number {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  color: #fff;
  margin: 0 auto var(--space-lg);
}

.step-card h3 {
  margin-bottom: var(--space-md);
}

.step-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ---------- Tools Grid ---------- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-md);
}

.tool-item {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-md) var(--space-lg);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  transition: all var(--transition);
}

.tool-item:hover {
  border-color: var(--primary-light);
  color: var(--primary);
}

.tool-item::before {
  content: "+";
  color: var(--primary);
  font-weight: 700;
}

/* ---------- Resource Cards ---------- */
.resource-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-xl);
}

.resource-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  transition: all var(--transition);
}

.resource-card:hover {
  border-color: var(--primary-light);
  box-shadow: var(--shadow-lg);
}

.resource-card span {
  display: inline-block;
  background: var(--bg-alt);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-md);
}

.resource-card h3 {
  font-size: 1rem;
  margin-bottom: var(--space-sm);
}

.resource-card p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* ---------- Spotlight Cards ---------- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.spotlight-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  text-align: center;
  transition: all var(--transition);
}

.spotlight-card:hover {
  border-color: var(--primary-light);
  box-shadow: var(--shadow-lg);
}

.spotlight-logo {
  width: 80px;
  height: 80px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-lg);
  color: #fff;
  font-size: 1.5rem;
  font-weight: 800;
}

.spotlight-card h3 {
  margin-bottom: var(--space-sm);
}

.spotlight-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ---------- Value Props ---------- */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.value-prop-card {
  text-align: center;
  padding: var(--space-xl);
}

.value-prop-icon {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-lg);
  color: #fff;
  font-size: 1.5rem;
}

.value-prop-card h3 {
  margin-bottom: var(--space-md);
}

.value-prop-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ---------- File Types Grid ---------- */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-md);
}

.file-type-item {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  text-align: center;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text);
  transition: all var(--transition);
}

.file-type-item:hover {
  border-color: var(--primary-light);
  color: var(--primary);
}

/* ---------- Scroll Animations ---------- */
.animate-on-scroll {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .why-tab-content-inner {
    grid-template-columns: 1fr;
  }

  .testimonial-card {
    flex: 0 0 calc(50% - var(--space-lg));
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--bg);
    flex-direction: column;
    padding: var(--space-lg);
    border-bottom: 1px solid var(--border);
    box-shadow: var(--shadow-lg);
    gap: var(--space-md);
  }

  .nav-links.open {
    display: flex;
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .testimonial-card {
    flex: 0 0 calc(100% - var(--space-lg));
  }

  .steps-grid,
  .spotlight-grid,
  .value-props-grid {
    grid-template-columns: 1fr;
  }

  .stats-bar-inner {
    gap: var(--space-xl);
  }

  .hero-cta {
    flex-direction: column;
    align-items: center;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .section {
    padding: var(--space-2xl) var(--space-md);
  }

  .hero {
    padding-top: 6rem;
  }

  .tab-toggle {
    flex-direction: column;
    width: 100%;
  }

  .tab-toggle-btn {
    width: 100%;
  }
}
